 document.body.appendChild(ov);const card=ov.firstElementChild;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const origin=()=>{if(!from||!from.getBoundingClientRect)return 'scale(.9)';const a=from.getBoundingClientRect(),b=card.getBoundingClientRect();const sx=Math.max(.08,a.width/b.width),sy=Math.max(.08,a.height/b.height);return `translate(${a.left+a.width/2-(b.left+b.width/2)}px, ${a.top+a.height/2-(b.top+b.height/2)}px) scale(${sx}, ${sy})`};
 const T0=origin();ov.animate([{background:'rgba(8,9,26,0)',backdropFilter:'blur(0px)'},{background:'rgba(8,9,26,.78)',backdropFilter:'blur(10px)'}],{duration:reduce?120:240,easing:'ease-out',fill:'forwards'});
 if(!reduce)card.animate([{transform:T0,opacity:.4,borderRadius:'40px'},{transform:'none',opacity:1,borderRadius:'28px'}],{duration:420,easing:'linear(0, 0.13, 0.4, 0.66, 0.83, 0.93, 0.98, 1)',fill:'backwards'});
 const close=()=>{document.removeEventListener('keydown',key);const v=ov.querySelector('video');v.pause();ov.animate([{background:'rgba(8,9,26,.78)'},{background:'rgba(8,9,26,0)'}],{duration:200,easing:'ease-in',fill:'forwards'});
  (reduce?card.animate([{opacity:1},{opacity:0}],{duration:150,fill:'forwards'}):card.animate([{transform:'none',opacity:1},{transform:origin(),opacity:0}],{duration:240,easing:'cubic-bezier(.4,0,1,1)',fill:'forwards'})).finished.then(()=>ov.remove())};
