/* ───── Pitch: enlaces del deck ───── */
A.DPitch=C=>class extends C{renderVals(){return {...g(),...super.renderVals()}}
 componentDidMount(){const N=()=>this._n||14;
  // Presentación personalizada: #pitch/<slug> carga el prospecto y la landing de su obra.
  const slug=String((this.props.params||[])[0]||'').toLowerCase();
  if(/^[a-z0-9-]{2,80}$/.test(slug))fetch('/api/v2/pitch/'+slug).then(r=>r.ok?r.json():Promise.reject(r.status)).then(j=>{if(j&&j.deck){this.setState({deck:j.deck});document.title='TADAA! × '+j.deck.prospect}}).catch(()=>TV.toast('No encontramos esa presentación; te mostramos la general.'));
  this._k=e=>{if(e.target.closest('input,textarea,select'))return;const n=N();if(e.key==='ArrowRight'||e.key===' '||e.key==='PageDown'){e.preventDefault();this.setState({i:(this.state.i+1)%n,idx:false,dx:1})}if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();this.setState({i:(this.state.i+n-1)%n,idx:false,dx:-1})}if(e.key==='Escape')this.setState({idx:false})};document.addEventListener('keydown',this._k);
  let x0=null;this._ts=e=>{x0=e.target.closest('iframe,input')?null:e.touches[0].clientX};this._te=e=>{if(x0==null)return;const dx=e.changedTouches[0].clientX-x0,n=N();if(Math.abs(dx)>50)this.setState({i:(this.state.i+(dx<0?1:n-1))%n,dx:dx<0?1:-1});x0=null};document.addEventListener('touchstart',this._ts,{passive:true});document.addEventListener('touchend',this._te,{passive:true})}
 componentWillUnmount(){document.removeEventListener('keydown',this._k);document.removeEventListener('touchstart',this._ts);document.removeEventListener('touchend',this._te)}};

